import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { TrendingUp, Shield, Eye, Activity } from 'lucide-react';

const MetricsPanel = ({ metrics, defenseStats, anomalyStats }) => {
  const COLORS = ['#10b981', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6'];

  const getDefenseChartData = () => {
    if (!defenseStats.blocksByDefense) return [];

    return Object.entries(defenseStats.blocksByDefense).map(([defense, count]) => ({
      name: defense,
      blocks: count
    }));
  };

  const getAnomalyChartData = () => {
    if (!anomalyStats.severityCounts) return [];

    return Object.entries(anomalyStats.severityCounts)
      .filter(([_, count]) => count > 0)
      .map(([severity, count]) => ({
        name: severity.charAt(0).toUpperCase() + severity.slice(1),
        value: count
      }));
  };

  const defenseChartData = getDefenseChartData();
  const anomalyChartData = getAnomalyChartData();

  const blockRate = defenseStats.blockRate || 0;
  const activeDefenses = defenseStats.activeDefenses?.length || 0;

  return (
    <div className="panel metrics-panel">
      <div className="panel-header">
        <h2>
          <TrendingUp size={20} />
          System Metrics & Analytics
        </h2>
      </div>

      <div className="metrics-summary">
        <div className="summary-card">
          <Shield size={24} className="summary-icon" style={{ color: '#3b82f6' }} />
          <div className="summary-content">
            <label>Defense Effectiveness</label>
            <p className="summary-value">{blockRate}%</p>
            <small>{defenseStats.blocked} / {defenseStats.totalProcessed} blocked</small>
          </div>
        </div>

        <div className="summary-card">
          <Activity size={24} className="summary-icon" style={{ color: '#10b981' }} />
          <div className="summary-content">
            <label>Active Defenses</label>
            <p className="summary-value">{activeDefenses}</p>
            <small>{defenseStats.activeDefenses?.join(', ') || 'None'}</small>
          </div>
        </div>

        <div className="summary-card">
          <Eye size={24} className="summary-icon" style={{ color: '#f59e0b' }} />
          <div className="summary-content">
            <label>Anomalies Detected</label>
            <p className="summary-value">{anomalyStats.totalAnomalies || 0}</p>
            <small>{anomalyStats.isLearning ? 'Learning Mode' : 'Active Detection'}</small>
          </div>
        </div>
      </div>

      {defenseChartData.length > 0 && (
        <div className="chart-section">
          <h3>Blocks by Defense Mechanism</h3>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={defenseChartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="name" stroke="#9ca3af" />
              <YAxis stroke="#9ca3af" />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: '#1f2937', 
                  border: '1px solid #374151',
                  borderRadius: '4px'
                }}
              />
              <Bar dataKey="blocks" fill="#3b82f6" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {anomalyChartData.length > 0 && (
        <div className="chart-section">
          <h3>Anomalies by Severity</h3>
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie
                data={anomalyChartData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={70}
                fill="#8884d8"
                dataKey="value"
              >
                {anomalyChartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: '#1f2937', 
                  border: '1px solid #374151',
                  borderRadius: '4px'
                }}
              />
            </PieChart>
          </ResponsiveContainer>
        </div>
      )}

      <div className="metrics-details">
        <h3>Detection Statistics</h3>
        <div className="stat-row">
          <span>Total Packets Processed:</span>
          <strong>{defenseStats.totalProcessed || 0}</strong>
        </div>
        <div className="stat-row">
          <span>Packets Allowed:</span>
          <strong style={{ color: '#10b981' }}>{defenseStats.allowed || 0}</strong>
        </div>
        <div className="stat-row">
          <span>Packets Blocked:</span>
          <strong style={{ color: '#ef4444' }}>{defenseStats.blocked || 0}</strong>
        </div>
        <div className="stat-row">
          <span>Baseline Status:</span>
          <strong style={{ color: anomalyStats.isLearning ? '#f59e0b' : '#10b981' }}>
            {anomalyStats.isLearning ? 'Learning' : 'Established'}
          </strong>
        </div>
      </div>

      {anomalyStats.severityCounts && (
        <div className="severity-breakdown">
          <h4>Anomaly Severity Breakdown</h4>
          <div className="severity-bars">
            {Object.entries(anomalyStats.severityCounts).map(([severity, count]) => {
              const total = anomalyStats.totalAnomalies || 1;
              const percentage = (count / total) * 100;
              const colors = {
                critical: '#ef4444',
                high: '#f59e0b',
                medium: '#3b82f6',
                low: '#10b981'
              };

              return (
                <div key={severity} className="severity-bar-item">
                  <label>{severity.charAt(0).toUpperCase() + severity.slice(1)}</label>
                  <div className="severity-bar-container">
                    <div 
                      className="severity-bar-fill"
                      style={{ 
                        width: `${percentage}%`,
                        background: colors[severity]
                      }}
                    />
                  </div>
                  <span>{count}</span>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default MetricsPanel;
